import{_ as t,a as o,b as s,c as n,d as a,e,f as i}from"./chunks/frames-viewer.OHjJ4sTJ.js";import{_ as l,o as g,c as p,a2 as d}from"./chunks/framework.Bzj1XTnB.js";const k=JSON.parse('{"title":"फ़्रेम, ओनियन स्किन और टाइमलाइन","description":"फ़्रेम जोड़ें और सजाएँ, ड्रॉइंग देर तक रोकें, आसपास के फ़्रेम देखें, लूप बनाएँ और एनिमेशन चलाएँ।","frontmatter":{"lang":"hi","slug":"frames-and-timeline","order":5,"title":"फ़्रेम, ओनियन स्किन और टाइमलाइन","description":"फ़्रेम जोड़ें और सजाएँ, ड्रॉइंग देर तक रोकें, आसपास के फ़्रेम देखें, लूप बनाएँ और एनिमेशन चलाएँ।"},"headers":[],"relativePath":"hi/frames-and-timeline.md","filePath":"hi/frames-and-timeline.md"}'),h={name:"hi/frames-and-timeline.md"};function m(c,r,u,_,f,b){return g(),p("div",null,[...r[0]||(r[0]=[d('<h1 id="फ़्रेम-ओनियन-स्किन-और-टाइमलाइन" tabindex="-1">फ़्रेम, ओनियन स्किन और टाइमलाइन <a class="header-anchor" href="#फ़्रेम-ओनियन-स्किन-और-टाइमलाइन" aria-label="Permalink to &quot;फ़्रेम, ओनियन स्किन और टाइमलाइन&quot;">​</a></h1><p>एनिमेशन फ़्रेम की एक कतार है। हर फ़्रेम एक ड्रॉइंग है; जब वे जल्दी-जल्दी एक के बाद एक चलते हैं तो चीज़ें हिलती दिखती हैं।</p><h2 id="फ़्रेम-की-पट्टी" tabindex="-1">फ़्रेम की पट्टी <a class="header-anchor" href="#फ़्रेम-की-पट्टी" aria-label="Permalink to &quot;फ़्रेम की पट्टी&quot;">​</a></h2><p>नीचे की पट्टी के ऊपर के छोटे चित्र आपके फ़्रेम हैं। मौजूदा फ़्रेम बीच में गुलाबी किनारे के साथ होता है।</p><ul><li>किसी फ़्रेम पर जाने के लिए उस पर <strong>टैप</strong> करें।</li><li><strong>पट्टी खींचें</strong> (या उसके ऊपर का गुलाबी हैंडल) — एनिमेशन में आगे-पीछे जाएँ। ऊपर मौजूदा फ़्रेम, कुल फ़्रेम और सेकंड दिखते हैं।</li><li><strong>गुलाबी +</strong> — मौजूदा फ़्रेम के बाद एक नया, खाली फ़्रेम जोड़ता है।</li><li><strong>▶</strong> एनिमेशन चलाता है, <strong>⏮ / ⏭</strong> पहले और आख़िरी फ़्रेम पर ले जाते हैं। रोकने के लिए स्क्रीन पर टैप करें।</li></ul><h2 id="फ़्रेम-के-काम" tabindex="-1">फ़्रेम के काम <a class="header-anchor" href="#फ़्रेम-के-काम" aria-label="Permalink to &quot;फ़्रेम के काम&quot;">​</a></h2><p>किसी फ़्रेम पर <strong>लॉन्ग-प्रेस</strong> करें।</p><p><img src="'+t+'" alt="फ़्रेम के काम"></p><ul><li><strong>Hold</strong> − / + — यह ड्रॉइंग ज़्यादा देर दिखाएँ (48 फ़्रेम तक), बिना दोबारा बनाए।</li><li><strong>Duplicate</strong>, <strong>Delete</strong>, <strong>Copy</strong>, <strong>Paste before</strong>, <strong>Paste after</strong>, <strong>Move left</strong>, <strong>Move right</strong>, <strong>Share</strong> (तस्वीर के रूप में)।</li><li>बंद करने के लिए <strong>Done</strong> या पट्टी के बाहर कहीं भी टैप करें।</li></ul><h2 id="ओनियन-स्किन" tabindex="-1">ओनियन स्किन <a class="header-anchor" href="#ओनियन-स्किन" aria-label="Permalink to &quot;ओनियन स्किन&quot;">​</a></h2><p>ओनियन स्किन पिछले और अगले फ़्रेम की हल्की परछाईं दिखाता है, ताकि अगली ड्रॉइंग सही जगह बने। नए प्रोजेक्ट में यह चालू रहता है और मूवी में कभी नहीं आता।</p><p><img src="'+o+'" alt="कैनवास पर ओनियन स्किन"></p><p>इसे <strong>⋮ → Onion skin → Edit</strong> में बदलें:</p><p><img src="'+s+'" alt="ओनियन स्किन सेटिंग"></p><ul><li><strong>Colored</strong> — पिछले फ़्रेम लाल, अगले फ़्रेम हरे।</li><li><strong>Looping</strong> — आख़िरी फ़्रेम पर पहला फ़्रेम भी दिखता है, लूप वाले एनिमेशन के लिए।</li><li><strong>Frames before / after</strong> — कितने आसपास के फ़्रेम दिखें (0–10)।</li><li><strong>Transparency before / after</strong> और <strong>Skip frames</strong>।</li></ul><h2 id="ग्रिड" tabindex="-1">ग्रिड <a class="header-anchor" href="#ग्रिड" aria-label="Permalink to &quot;ग्रिड&quot;">​</a></h2><p><strong>⋮ → Grid</strong> कैनवास पर गाइड लाइनें बनाता है, दूरी सही रखने में मदद के लिए। <strong>Edit</strong> से लाइनों की दूरी और गहराई बदलें। ग्रिड मूवी में कभी नहीं आता।</p><h2 id="पूरी-टाइमलाइन" tabindex="-1">पूरी टाइमलाइन <a class="header-anchor" href="#पूरी-टाइमलाइन" aria-label="Permalink to &quot;पूरी टाइमलाइन&quot;">​</a></h2><p>ऊपर <strong>TIMELINE</strong> टैप करें — हर फ़्रेम, उसकी असली लंबाई के साथ, आपकी लेयर और ऑडियो के साथ बड़ा दिखता है।</p><p><img src="'+n+'" alt="टाइमलाइन"></p><ul><li>किसी फ़्रेम पर जाने के लिए <strong>टैप</strong> करें।</li><li>मौजूदा फ़्रेम के किनारे की <strong>गुलाबी पकड़ खींचें</strong> — फ़्रेम ज़्यादा या कम देर तक रुकता है।</li><li><strong>लॉन्ग-प्रेस</strong> करके फ़्रेम चुनें; खींचते रहें तो वह हिलता है। कई चुनने हों तो और पर टैप करें।</li><li>टाइमलाइन ज़ूम करने के लिए <strong>पिंच</strong> करें।</li><li>नीचे बाएँ <strong>Hold</strong> कार्ड चुने फ़्रेम का होल्ड बदलता है; दाईं ओर का प्रीव्यू एनिमेशन चलाता है।</li></ul><p><img src="'+a+'" alt="कई फ़्रेम चुने हुए"></p><h3 id="ग्रुप-और-लूप" tabindex="-1">ग्रुप और लूप <a class="header-anchor" href="#ग्रुप-और-लूप" aria-label="Permalink to &quot;ग्रुप और लूप&quot;">​</a></h3><p>कुछ फ़्रेम चुनें और <strong>Group</strong> टैप करें। अब ग्रुप को <strong>Loop</strong> से दोहरा सकते हैं — चलने की साइकिल या कई बार झपकती आँख के लिए बढ़िया। <strong>Ungroup</strong> ग्रुप हटाता है और <strong>Split</strong> ग्रुप को दो में बाँटता है।</p><p><img src="'+e+'" alt="लूप के साथ फ़्रेम ग्रुप"></p><p>नीचे की पट्टी में <strong>Undo</strong>, <strong>Redo</strong>, <strong>Select / Deselect</strong>, <strong>Duplicate</strong>, <strong>Copy</strong>, <strong>Paste</strong>, <strong>Delete</strong> और <strong>Layer</strong> भी हैं। बंद करने के लिए <strong>TIMELINE</strong> फिर टैप करें (या प्रीव्यू पर ✕)।</p><h2 id="सारे-फ़्रेम-एक-साथ" tabindex="-1">सारे फ़्रेम एक साथ <a class="header-anchor" href="#सारे-फ़्रेम-एक-साथ" aria-label="Permalink to &quot;सारे फ़्रेम एक साथ&quot;">​</a></h2><p><strong>⋮ → Frames</strong> हर फ़्रेम एक ग्रिड में दिखाता है। खोलने के लिए टैप करें, चुनने के लिए लॉन्ग-प्रेस (फिर डुप्लिकेट, डिलीट, कॉपी, पेस्ट या शेयर), या हिलाने के लिए लॉन्ग-प्रेस करके खींचें।</p><p><img src="'+i+'" alt="फ़्रेम व्यूअर"></p><h2 id="रफ़्तार-और-टाइमिंग" tabindex="-1">रफ़्तार और टाइमिंग <a class="header-anchor" href="#रफ़्तार-और-टाइमिंग" aria-label="Permalink to &quot;रफ़्तार और टाइमिंग&quot;">​</a></h2><ul><li><strong>Frames per second</strong> (Project settings) पूरे एनिमेशन की रफ़्तार तय करता है। 12 fps से शुरुआत अच्छी है; 24 fps फ़िल्म जैसा दिखता है; 4–8 fps जानबूझकर झटकेदार दिखता है।</li><li><strong>Timing</strong> — <em>On twos</em> हर ड्रॉइंग दो फ़्रेम तक रोकता है, यानी उतनी ही लंबाई के लिए आधी ड्रॉइंग बनानी पड़ती हैं। अकेले फ़्रेम को फ़्रेम के काम वाली पट्टी या टाइमलाइन से रोकें।</li></ul>',31)])])}const x=l(h,[["render",m]]);export{k as __pageData,x as default};
